//! Self-hosted Bible text.
//!
//! The verse files in `data/bible/` are generated by
//! `scripts/build_bible_data.py` from eBible.org and compiled into the binary,
//! so verse text points straight into the executable's read-only data: no
//! copies, no file I/O and no network at runtime. See `data/bible/NOTICE.md`
//! for sources and licences.

use std::collections::HashMap;
use std::sync::LazyLock;

use serde::Serialize;

use crate::error::AppError;

/// Longest chapter span one request may cover.
pub const MAX_CHAPTER_SPAN: u32 = 4;
/// Most verses one request may return.
pub const MAX_VERSES: usize = 200;

