/// A verse row. `end > start` when the source merges several verses
/// (e.g. Romans 16:24-25 in the Malayalam IRV).
#[derive(Debug, Clone, Copy)]
pub struct Verse {
    pub start: u32,
    pub end: u32,
    pub text: &'static str,
}

pub struct Book {
    pub code: &'static str,
    pub name: &'static str,
    /// `chapters[0]` is chapter 1.
    pub chapters: Vec<Vec<Verse>>,
}

pub struct Translation {
    pub info: &'static TranslationInfo,
    pub books: Vec<Book>,
    index: HashMap<&'static str, usize>,
}

impl Translation {
    pub fn book(&self, code: &str) -> Option<&Book> {
        self.index
            .get(code.to_ascii_uppercase().as_str())
            .map(|&i| &self.books[i])
    }

    pub fn verse_count(&self) -> usize {
        self.books
            .iter()
            .flat_map(|b| b.chapters.iter())
            .map(|c| c.len())
            .sum()
    }
}

/// Parses one generated `.tsv` file. Panics on malformed data: the files are
/// compiled in, so a bad file must fail the first test run, not production.
pub fn parse(info: &'static TranslationInfo) -> Translation {
    let mut books: Vec<Book> = Vec::new();
    let mut index = HashMap::new();
    for (n, line) in info.data.lines().enumerate() {
        let fail = |what: &str| panic!("{} line {}: {}", info.id, n + 1, what);
        let mut parts = line.splitn(4, '\t');
        let (a, b, c) = (parts.next(), parts.next(), parts.next());
        if a == Some("#name") {
            let (Some(code), Some(name)) = (b, c) else {
                fail("bad #name")
            };
            index.insert(code, books.len());
            books.push(Book {
                code,
                name,
                chapters: Vec::new(),
            });
            continue;
        }
        let (Some(code), Some(ch), Some(label), Some(text)) = (a, b, c, parts.next()) else {
            fail("expected 4 columns")
        };
        let Some(&bi) = index.get(code) else {
            fail("unknown book")
        };
        let ch: usize = ch.parse().unwrap_or_else(|_| fail("bad chapter"));
        let (start, end) = match label.split_once('-') {
            Some((s, e)) => (s.parse(), e.parse()),
            None => (label.parse(), label.parse()),
        };
        let (Ok(start), Ok(end)) = (start, end) else {
            fail("bad verse")
        };
        let chapters = &mut books[bi].chapters;
        if ch == 0 {
            fail("chapter 0");
        }
        while chapters.len() < ch {
            chapters.push(Vec::new());
        }
        chapters[ch - 1].push(Verse { start, end, text });
    }
    Translation { info, books, index }
}

static LIBRARY: LazyLock<HashMap<&'static str, Translation>> =
    LazyLock::new(|| TRANSLATIONS.iter().map(|t| (t.id, parse(t))).collect());

/// Loads every translation; call once at startup so the first request is not
/// the one that pays for parsing.
pub fn init() {
    for t in TRANSLATIONS {
        let tr = &LIBRARY[t.id];
        tracing::info!("Bible text loaded: {} ({} verses)", t.id, tr.verse_count());
    }
}

pub fn translation(id: &str) -> Result<&'static Translation, AppError> {
    LIBRARY
        .get(id.to_ascii_lowercase().as_str())
        .ok_or_else(|| AppError::NotFound(format!("Unknown Bible version '{id}'")))
}

#[derive(Debug, Default, Clone)]
pub struct VerseQuery {
    pub book: String,
    pub chapter: u32,
    pub verse_start: Option<u32>,
    pub verse_end: Option<u32>,
    pub end_chapter: Option<u32>,
}

#[derive(Debug, Serialize, PartialEq)]
pub struct VerseOut {
    pub chapter: u32,
    pub verse: u32,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub verse_end: Option<u32>,
    pub text: &'static str,
}

#[derive(Debug, Serialize)]
pub struct Passage {
    pub book: &'static str,
    pub book_name: &'static str,
    pub reference: String,
    pub verses: Vec<VerseOut>,
}

/// Parses a required/optional query value as a positive integer.
pub fn positive_int(name: &str, raw: Option<&str>) -> Result<Option<u32>, AppError> {
    match raw.map(str::trim) {
        None | Some("") => Ok(None),
        Some(s) => match s.parse::<u32>() {
            Ok(n) if n > 0 && n < 100_000 => Ok(Some(n)),
            _ => Err(AppError::BadRequest(format!(
                "'{name}' must be a positive integer"
            ))),
        },
    }
}

/// Selects the requested verses. Without `verse_start` the whole chapter is
/// returned; without `verse_end` a single verse (or, when `end_chapter` is
/// given, everything to the end of that chapter).
pub fn passage(tr: &'static Translation, q: &VerseQuery) -> Result<Passage, AppError> {
    let book = tr
        .book(q.book.trim())
        .ok_or_else(|| AppError::NotFound(format!("Unknown book '{}'", q.book)))?;
    let chapter_count = book.chapters.len() as u32;
    let start_ch = q.chapter;
    let end_ch = q.end_chapter.unwrap_or(start_ch);
    if start_ch > chapter_count {
        return Err(AppError::NotFound(format!(
            "{} has {} chapters",
            book.name, chapter_count
        )));
    }
    if end_ch < start_ch {
        return Err(AppError::BadRequest(
            "'end_chapter' must not be before 'chapter'".into(),
        ));
    }
    if end_ch - start_ch >= MAX_CHAPTER_SPAN {
        return Err(AppError::BadRequest(format!(
            "A request may span at most {MAX_CHAPTER_SPAN} chapters"
        )));
    }
    let end_ch = end_ch.min(chapter_count);
    let last_verse = |ch: u32| {
        book.chapters[(ch - 1) as usize]
            .last()
            .map(|v| v.end)
            .unwrap_or(0)
    };

    let vs = q.verse_start.unwrap_or(1);
    let ve = match (q.verse_start, q.verse_end, q.end_chapter) {
        (_, Some(e), _) => e,
        (Some(s), None, None) => s,
        _ => last_verse(end_ch),
    };
    if vs > last_verse(start_ch) {
        return Err(AppError::NotFound(format!(
            "{} {} has {} verses",
            book.name,
            start_ch,
            last_verse(start_ch)
        )));
    }
    if end_ch == start_ch && ve < vs {
        return Err(AppError::BadRequest(
            "'verse_end' must not be before 'verse_start'".into(),
        ));
    }
    let ve = ve.min(last_verse(end_ch));

    let mut verses = Vec::new();
    for ch in start_ch..=end_ch {
        let lo = if ch == start_ch { vs } else { 1 };
        let hi = if ch == end_ch { ve } else { u32::MAX };
        for v in &book.chapters[(ch - 1) as usize] {
            if v.end >= lo && v.start <= hi {
                verses.push(VerseOut {
                    chapter: ch,
                    verse: v.start,
                    verse_end: (v.end != v.start).then_some(v.end),
                    text: v.text,
                });
                if verses.len() > MAX_VERSES {
                    return Err(AppError::BadRequest(format!(
                        "A request may return at most {MAX_VERSES} verses"
                    )));
                }
            }
        }
    }
    if verses.is_empty() {
        return Err(AppError::NotFound("No verses in that range".into()));
    }

    let whole_chapter = q.verse_start.is_none() && q.end_chapter.is_none();
    let reference = if whole_chapter {
        format!("{} {}", book.name, start_ch)
    } else if start_ch == end_ch && vs == ve {
        format!("{} {}:{}", book.name, start_ch, vs)
    } else if start_ch == end_ch {
        format!("{} {}:{}-{}", book.name, start_ch, vs, ve)
    } else {
        format!("{} {}:{}-{}:{}", book.name, start_ch, vs, end_ch, ve)
    };

    Ok(Passage {
        book: book.code,
        book_name: book.name,
        reference,
        verses,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn q(book: &str, ch: u32, vs: Option<u32>, ve: Option<u32>, ec: Option<u32>) -> VerseQuery {
        VerseQuery {
            book: book.into(),
            chapter: ch,
            verse_start: vs,
            verse_end: ve,
            end_chapter: ec,
        }
    }

    fn bsb() -> &'static Translation {
        translation("bsb").unwrap()
    }

    #[test]
    fn every_translation_has_66_books_and_expected_verse_counts() {
        for t in TRANSLATIONS {
            let tr = translation(t.id).unwrap();
            assert_eq!(tr.books.len(), 66, "{}", t.id);
            let n = tr.verse_count();
            assert!((31_000..=31_110).contains(&n), "{}: {n}", t.id);
            assert_eq!(tr.book("JHN").unwrap().chapters.len(), 21);
        }
    }

    #[test]
    fn single_verse() {
        let p = passage(bsb(), &q("jhn", 3, Some(16), None, None)).unwrap();
        assert_eq!(p.reference, "John 3:16");
        assert_eq!(p.verses.len(), 1);
        assert!(p.verses[0].text.starts_with("For God so loved the world"));
    }

    #[test]
    fn localized_reference_and_text() {
        for id in ["irv-hi", "irv-ml", "sv-ml"] {
            let p = passage(translation(id).unwrap(), &q("JHN", 3, Some(16), None, None)).unwrap();
            assert!(!p.reference.starts_with("John"), "{id}");
            assert!(!p.verses[0].text.contains('\\'), "{id}");
        }
    }

    #[test]
    fn hindi_inline_cross_references_are_removed() {
        let p = passage(
            translation("irv-hi").unwrap(),
            &q("GEN", 1, Some(1), None, None),
        )
        .unwrap();
        assert!(!p.verses[0].text.contains('('));
    }

    #[test]
    fn verse_range_and_whole_chapter() {
        let p = passage(bsb(), &q("JHN", 3, Some(16), Some(18), None)).unwrap();
        assert_eq!(p.reference, "John 3:16-18");
        assert_eq!(
            p.verses.iter().map(|v| v.verse).collect::<Vec<_>>(),
            [16, 17, 18]
        );

        let p = passage(bsb(), &q("PSA", 23, None, None, None)).unwrap();
        assert_eq!(p.reference, "Psalms 23");
        assert_eq!(p.verses.len(), 6);
    }

    #[test]
    fn cross_chapter_range() {
        let p = passage(bsb(), &q("JHN", 3, Some(35), Some(2), Some(4))).unwrap();
        assert_eq!(p.reference, "John 3:35-4:2");
        let first = &p.verses[0];
        let last = p.verses.last().unwrap();
        assert_eq!((first.chapter, first.verse), (3, 35));
        assert_eq!((last.chapter, last.verse), (4, 2));
        assert_eq!(p.verses.len(), 4);
    }

    #[test]
    fn verse_end_is_clamped_to_chapter_end() {
        let p = passage(bsb(), &q("JHN", 3, Some(35), Some(99), None)).unwrap();
        assert_eq!(p.verses.last().unwrap().verse, 36);
    }

    #[test]
    fn merged_verses_are_found_by_either_number() {
        let tr = translation("irv-ml").unwrap();
        let p = passage(tr, &q("ROM", 16, Some(25), None, None)).unwrap();
        assert_eq!(p.verses[0].verse, 24);
        assert_eq!(p.verses[0].verse_end, Some(25));
    }

    #[test]
    fn limits_and_errors() {
        // 5 chapters
        assert!(matches!(
            passage(bsb(), &q("GEN", 1, None, None, Some(5))),
            Err(AppError::BadRequest(_))
        ));
        // 4 chapters of Psalm 119 range > 200 verses
        assert!(matches!(
            passage(bsb(), &q("PSA", 118, Some(1), Some(176), Some(119))),
            Err(AppError::BadRequest(_))
        ));
        assert!(matches!(
            passage(bsb(), &q("JHN", 3, Some(5), Some(4), None)),
            Err(AppError::BadRequest(_))
        ));
        assert!(matches!(
            passage(bsb(), &q("JHN", 3, Some(4), None, Some(2))),
            Err(AppError::BadRequest(_))
        ));
        assert!(matches!(
            passage(bsb(), &q("XYZ", 1, None, None, None)),
            Err(AppError::NotFound(_))
        ));
        assert!(matches!(
            passage(bsb(), &q("JHN", 22, None, None, None)),
            Err(AppError::NotFound(_))
        ));
        assert!(matches!(
            passage(bsb(), &q("JHN", 3, Some(37), None, None)),
            Err(AppError::NotFound(_))
        ));
        assert!(translation("niv").is_err());
    }

    #[test]
    fn positive_int_validation() {
        assert_eq!(positive_int("x", Some("16")).unwrap(), Some(16));
        assert_eq!(positive_int("x", None).unwrap(), None);
        for bad in ["0", "-1", "1.5", "abc", "999999"] {
            assert!(positive_int("x", Some(bad)).is_err(), "{bad}");
        }
    }
}
